INSERT INTO "Blogs" (id, title, destination, summary, content, image_url, tour_id) VALUES (1, 'Hà Nội về đêm và hành trình ẩm thực cổ điển', 'Hà Nội', 'Không gian phố cổ lúc lên đèn là thời điểm đẹp nhất để thử món ăn vỉa hè.', 'Pho co ve dem tao cam giac vua than quen vua soi dong. Ban co the bat dau tu Ho Guom, ghe Ta Hien va ket thuc bang mot ly cafe trung.', 'https://images.unsplash.com/photo-1563492065599-3520f775eeed', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO "Blogs" (id, title, destination, summary, content, image_url, tour_id) VALUES (2, 'Đà Nẵng – Hội An: 3 ngày cân bằng giữa biển và phố', 'Đà Nẵng', 'Hành trình kết hợp cảnh biển, ẩm thực miền Trung và nét đẹp di sản.', 'Ngay dau kham pha Son Tra, ngay hai di Hoi An, ngay ba danh cho beach club va cac quan an dia phuong.', 'https://images.unsplash.com/photo-1527838832700-5059252407fa', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO "Blogs" (id, title, destination, summary, content, image_url, tour_id) VALUES (3, 'Nha Trang cho người muốn nghỉ dưỡng nhưng vẫn năng động', 'Nha Trang', 'Biển xanh và các hoạt động trên đảo là điểm nhấn của hành trình.', 'Neu ban thich lan ngam san ho va an hai san tuoi, day la chuyen di rat dang thu.', 'https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86', 3) ON CONFLICT (id) DO NOTHING;
